    const rect = toRect(item);
    const px = e.clientX - box.left;
    const py = e.clientY - box.top;
    session.current = {
      id,
      kind,
      startLayout: layout,
      anchorX: kind === 'move' ? px - rect.left : px,
      anchorY: kind === 'move' ? py - rect.top : py,
      startRect: rect,
      clientX: e.clientX,
      clientY: e.clientY,
      targetKey: '',
    };
