/* Уголок для изменения размера */
.dash-grid__resize {
  position: absolute;
  right: 0;
  bottom: 0;
  z-index: 2;
  width: 24px;
  height: 24px;
  cursor: nwse-resize;
  touch-action: none;
}

.dash-grid__resize::after {
  content: '';
  position: absolute;
  right: 6px;
  bottom: 6px;
  width: 8px;
  height: 8px;
  border-right: 2px solid var(--g-color-line-generic-accent);
  border-bottom: 2px solid var(--g-color-line-generic-accent);
