  border-color: var(--g-color-line-brand);
}

body.dash-grid-dragging {
  user-select: none;
  -webkit-user-select: none;
  cursor: nwse-resize;
}

body.dash-grid-dragging_move {
  cursor: grabbing;
}

body.dash-grid-dragging * {
  cursor: inherit !important;
}

.dash-grid__live,
.dash-grid__sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

