/* Роли цветов графиков. Значения — валидированная референсная палитра (светлая тема). */
.viz-root {
  --viz-surface: var(--g-color-base-float);
  --viz-series-1: #2a78d6;
  --viz-series-2: #eb6834;
  --viz-series-3: #1baf7a;
  --viz-series-4: #eda100;
  --viz-series-5: #e87ba4;
  --viz-track: #cde2fb;
  --viz-ink: #0b0b0b;
  --viz-ink-secondary: #52514e;
  --viz-muted: #898781;
  --viz-grid: #e1e0d9;
  --viz-axis: #c3c2b7;
  --viz-good: #006300;
  --viz-bad: #d03b3b;
}

.viz-chart {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
  height: 100%;
  min-height: 0;
}

.viz-chart__plot {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: visible;
}

.viz-chart__plot > svg {
  position: absolute;
  inset: 0;
  overflow: visible;
}

.viz-grid {
  stroke: var(--viz-grid);
  stroke-width: 1;
  shape-rendering: crispEdges;
}

.viz-axis {
  stroke: var(--viz-axis);
  stroke-width: 1;
  shape-rendering: crispEdges;
}

.viz-crosshair {
  stroke: var(--viz-muted);
  stroke-width: 1;
  shape-rendering: crispEdges;
}

.viz-tick {
  font-size: 11px;
  fill: var(--viz-muted);
  font-variant-numeric: tabular-nums;
}

.viz-cat-label {
  font-size: 12px;
  fill: var(--viz-ink-secondary);
}

.viz-value-label,
.viz-direct-label {
  font-size: 12px;
  fill: var(--viz-ink);
}

.viz-direct-label {
  fill: var(--viz-ink-secondary);
}

.viz-focusable {
  outline: none;
}

.viz-focusable:focus-visible {
  outline: 2px solid var(--g-color-line-focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Легенда */
.viz-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12px;
  line-height: 16px;
  color: var(--viz-ink-secondary);
}

.viz-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.viz-legend__key_line {
  width: 14px;
  height: 2px;
  border-radius: 1px;
}

.viz-legend__key_rect {
  width: 10px;
  height: 10px;
  border-radius: 2px;
}

/* Подсказка */
.viz-tooltip {
  position: absolute;
  z-index: 5;
  min-width: 120px;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--g-color-base-float);
  box-shadow:
    0 0 0 1px rgba(11, 11, 11, 0.1),
    0 8px 20px rgba(0, 0, 0, 0.12);
  pointer-events: none;
  font-size: 12px;
  line-height: 16px;
  white-space: nowrap;
}

.viz-tooltip__title {
  margin-bottom: 4px;
  color: var(--viz-ink-secondary);
}

.viz-tooltip__row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.viz-tooltip__key_line {
  width: 12px;
  height: 2px;
  border-radius: 1px;
}

.viz-tooltip__key_rect {
  width: 8px;
  height: 8px;
  border-radius: 2px;
}

.viz-tooltip__value {
  font-weight: 600;
  color: var(--viz-ink);
  font-variant-numeric: tabular-nums;
}

.viz-tooltip__label {
  color: var(--viz-ink-secondary);
}

/* Сегментированная полоса */
.viz-segmented {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 14px;
  height: 100%;
}

.viz-segmented__bar {
  position: relative;
  height: 28px;
  flex: none;
}

.viz-segmented__part {
  position: absolute;
  top: 0;
  height: 28px;
  box-sizing: border-box;
  padding-left: 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  line-height: 28px;
  white-space: nowrap;
  transition: opacity 120ms;
}

/* Спарклайн */
.viz-spark {
  width: 100%;
}

.viz-spark > svg {
  display: block;
  overflow: visible;
}

