      const items: Layout = [];
      for (const it of raw.layout) {
        if (!it || typeof it.i !== 'string' || !WIDGET_BY_ID.has(it.i) || seen.has(it.i)) continue;
        if (![it.x, it.y, it.w, it.h].every((v) => Number.isFinite(v))) continue;
        seen.add(it.i);
        items.push(itemFor(it.i, { x: it.x, y: it.y, w: it.w, h: it.h }));
      }
      return { layout: fixOverlaps(items, COLS), compact: raw.compact === true };
    }
  } catch {
    // повреждённые данные — используем раскладку по умолчанию
  }
  return { layout: defaultLayout(), compact: false };
}

const RANGES: { value: RangeKey; content: string }[] = [
  { value: '7', content: '7 дней' },
  { value: '30', content: '30 дней' },
  { value: '90', content: '90 дней' },
];

export function App() {
  const [initial] = useState(load);
  const [layout, setLayout] = useState<Layout>(initial.layout);
  const [packed, setPacked] = useState(initial.compact);
  const [editing, setEditing] = useState(true);
  const [range, setRange] = useState<RangeKey>('30');
  const [tableView, setTableView] = useState<Record<string, boolean>>({});

  const data = useMemo(() => makeData(range), [range]);

  useEffect(() => {
    try {
      const plain = layout.map(({ i, x, y, w, h }) => ({ i, x, y, w, h }));
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ layout: plain, compact: packed }));
    } catch {
      // хранилище недоступно — раскладка просто не сохранится
    }
  }, [layout, packed]);

  const apply = useCallback((next: Layout) => setLayout(packed ? compactLayout(next) : next), [packed]);

  const hidden = WIDGETS.filter((w) => !layout.some((it) => it.i === w.id));

  const addWidget = (id: string) => {
    const def = WIDGET_BY_ID.get(id)!;
    const spot = findFreeSpot(layout, def.layout.w, def.layout.h, COLS);
    apply([...layout, itemFor(id, { ...spot, w: def.layout.w, h: def.layout.h })]);
  };

  const removeWidget = (id: string) => apply(layout.filter((it) => it.i !== id));

  const togglePacked = (on: boolean) => {
    setPacked(on);
    if (on) setLayout(compactLayout(layout));
  };

  const reset = () => {
    setLayout(defaultLayout());
    setPacked(false);
    setTableView({});
  };

  const getLabel = useCallback((id: string) => WIDGET_BY_ID.get(id)?.title ?? id, []);

  return (
    <div className="dashboard viz-root">
      <header className="dashboard__header">
        <div>
          <Text as="h1" variant="header-2" className="dashboard__title">
            Продажи интернет-магазина
          </Text>
          <Text color="secondary">
            {editing
              ? 'Перетаскивайте виджеты за заголовок, тяните за правый нижний угол, чтобы изменить размер.'
              : 'Раскладка зафиксирована. Включите редактирование, чтобы переставить виджеты.'}
          </Text>
        </div>
        <div className="dashboard__controls">
          <Switch checked={editing} onUpdate={setEditing} content="Редактирование" />
          <Switch
            checked={packed}
            onUpdate={togglePacked}
            disabled={!editing}
            content="Прижимать вверх"
            title="Автоматически поднимать виджеты, убирая пустые строки"
          />
          <DropdownMenu
            disabled={!editing || hidden.length === 0}
            items={hidden.map((w) => ({ text: w.title, action: () => addWidget(w.id) }))}
            renderSwitcher={(props) => (
              <Button {...props} view="outlined" disabled={!editing || hidden.length === 0}>
                <Icon data={Plus} size={16} />
                Добавить виджет
              </Button>
            )}
          />
          <Button view="flat" onClick={reset} disabled={!editing}>
            <Icon data={ArrowRotateLeft} size={16} />
            Сбросить
          </Button>
        </div>
      </header>

      <div className="dashboard__filters">
        <Text color="secondary">Период</Text>
        <SegmentedRadioGroup<RangeKey> value={range} onUpdate={setRange} options={RANGES} />
      </div>

      {layout.length === 0 ? (
        <div className="dashboard__empty">
          <Text color="secondary">На дашборде нет виджетов.</Text>
          <Button view="action" onClick={() => setLayout(defaultLayout())}>
            Вернуть все виджеты
          </Button>
        </div>
      ) : (
        <DashboardGrid
          layout={layout}
          onLayoutChange={setLayout}
          editable={editing}
          compact={packed}
          cols={COLS}
          getLabel={getLabel}
          renderItem={(id, ctx) => {
            const def = WIDGET_BY_ID.get(id)!;
            const asTable = !!def.table && !!tableView[id];
            return (
              <WidgetCard
                title={def.title}
                ctx={ctx}
                scrollable={def.scrollable}
                showTable={asTable}
                onToggleTable={def.table ? () => setTableView((t) => ({ ...t, [id]: !t[id] })) : undefined}
                onRemove={() => removeWidget(id)}
              >
                {asTable ? <WidgetDataTable table={def.table!(data)} /> : def.render(data, range)}
              </WidgetCard>
            );
          }}
        />
      )}
    </div>
  );
}

args.content:
body {
  margin: 0;
  background: var(--g-color-base-background);
}

.dashboard {
  box-sizing: border-box;
  max-width: 1440px;
  margin: 0 auto;
  padding: 24px;
}

.dashboard__header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px 24px;
  margin-bottom: 20px;
}

.dashboard__title {
  margin: 0 0 4px;
}

.dashboard__controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 16px;
}

.dashboard__filters {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}

.dashboard__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 64px 0;
}

/* ——— Карточка виджета ——— */

.widget {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  height: 100%;
  border-radius: 12px;
  background: var(--g-color-base-float);
  box-shadow: 0 0 0 1px var(--g-color-line-generic);
  overflow: hidden;
}

.widget_editable:hover,
.widget_editable:focus-within {
  box-shadow: 0 0 0 1px var(--g-color-line-generic-accent);
}

.widget_dragging {
  box-shadow: 0 0 0 2px var(--g-color-line-brand);
}

.widget__header {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: none;
  min-height: 40px;
  padding: 4px 6px 0 14px;
}

.widget_editable .widget__header {
  padding-left: 6px;
  cursor: grab;
  touch-action: none;
}

.widget__grip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--g-color-text-secondary);
  cursor: grab;
  touch-action: none;
}

.widget__grip:hover {
  background: var(--g-color-base-generic-hover);
}

.widget__grip:focus-visible {
  outline: 2px solid var(--g-color-line-focus);
  outline-offset: 0;
}

.widget__title {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--g-color-text-primary);
}

.widget__actions {
  display: flex;
  flex: none;
  gap: 2px;
  cursor: default;
}

.widget__body {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  padding: 8px 16px 16px;
}

.widget__body_scroll {
  overflow: auto;
  padding-top: 4px;
}

.widget-table {
  width: 100%;
}

.widget-table td,
.widget-table th {
  font-variant-numeric: tabular-nums;
}

/* ——— Плитка показателя ——— */

.stat {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}

.stat__value {
  font-size: 28px;
  font-weight: 600;
  line-height: 32px;
  color: var(--viz-ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.stat__delta {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 6px;
  margin-top: 2px;
  font-size: 12px;
  line-height: 16px;
}

.stat__delta_good {
  color: var(--viz-good);
}

.stat__delta_bad {
  color: var(--g-color-text-danger);
}

.stat__period {
  color: var(--viz-ink-secondary);
}

.stat__spark {
  margin-top: auto;
  padding-top: 4px;
}

/* ——— Прогресс к плану ——— */

.meter {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  height: 100%;
}

.meter__head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 12px;
}

.meter__value {
  font-size: 28px;
  font-weight: 600;
  line-height: 32px;
  color: var(--viz-ink);
}

.meter__caption {
  font-size: 13px;
  color: var(--viz-ink-secondary);
}

.meter__track {
  height: 8px;
  border-radius: 4px;
  background: var(--viz-track);
  overflow: hidden;
}

.meter__fill {
  height: 100%;
  border-radius: 4px;
  background: var(--viz-series-1);
}

