args.command:
(npx vite preview --port 4173 --strictPort >/tmp/shot/preview.log 2>&1 &) ; cat > /tmp/shot/run.mjs <<'EOF'
import { chromium } from 'playwright';
const out = '/tmp/shot';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1400, height: 1100 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto('http://localhost:4173/');
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForTimeout(500);
await page.screenshot({ path: `${out}/1-initial.png`, fullPage: true });

const box = async (title) => {
  const h = page.locator('section.widget', { has: page.locator('h2', { hasText: title }) }).first();
  return h.boundingBox();
};
const layout = () => page.evaluate(() => JSON.parse(localStorage.getItem('viz-dashboard:v1')).layout.map(i => `${i.i}:${i.x},${i.y},${i.w}x${i.h}`).join(' | '));

// Hover line chart
const tb = await box('Посещаемость');
await page.mouse.move(tb.x + tb.width * 0.6, tb.y + tb.height * 0.5);
await page.waitForTimeout(100);
await page.screenshot({ path: `${out}/2-hover.png`, clip: { x: tb.x - 10, y: tb.y - 10, width: tb.width + 20, height: tb.height + 20 } });

// Drag "Выручка" header onto "Конверсия" position mid-drag screenshot
const rb = await box('Выручка');
const cb = await box('Конверсия');
await page.mouse.move(rb.x + 60, rb.y + 18);
await page.mouse.down();
for (let k = 1; k <= 10; k++) await page.mouse.move(rb.x + 60 + (cb.x - rb.x) * k / 10, rb.y + 18 + 30 * k / 10);
await page.waitForTimeout(250);
await page.screenshot({ path: `${out}/3-dragging.png`, clip: { x: 0, y: 0, width: 1400, height: 600 } });
await page.mouse.up();
await page.waitForTimeout(300);
console.log('after drag  :', await layout());

// Resize traffic chart: drag bottom-right corner left by ~2 cols and down by 1 row
const tb2 = await box('Посещаемость');
await page.mouse.move(tb2.x + tb2.width - 8, tb2.y + tb2.height - 8);
await page.mouse.down();
for (let k = 1; k <= 10; k++) await page.mouse.move(tb2.x + tb2.width - 8 - 220 * k / 10, tb2.y + tb2.height - 8 + 90 * k / 10);
await page.mouse.up();
await page.waitForTimeout(300);
console.log('after resize:', await layout());

// Keyboard: focus grip of "Заказы", move right, shift+down
await page.getByRole('button', { name: 'Переместить виджет «Заказы»' }).focus();
await page.keyboard.press('ArrowRight');
await page.keyboard.press('Shift+ArrowDown');
await page.waitForTimeout(300);
console.log('after keys  :', await layout());
console.log('live region :', await page.locator('.dash-grid__live').textContent());

// Escape cancels drag
const before = await layout();
const pb = await box('План выручки');
await page.mouse.move(pb.x + 80, pb.y + 18); await page.mouse.down();
await page.mouse.move(pb.x + 400, pb.y - 300, { steps: 8 });
await page.keyboard.press('Escape'); await page.mouse.up();
await page.waitForTimeout(200);
console.log('escape keeps layout:', before === await layout());

// Table toggle and reload persistence
await page.getByRole('button', { name: 'Показать таблицей' }).first().click();
await page.reload(); await page.waitForTimeout(400);
console.log('persisted   :', await layout());
await page.screenshot({ path: `${out}/4-after.png`, fullPage: true });

// Narrow
await page.setViewportSize({ width: 600, height: 900 });
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/5-narrow.png` });
console.log('errors:', errors);
await browser.close();
EOF
sleep 2; cd /tmp/shot && node run.mjs

